CREATE TABLE "corporate_kyc_applications" ("id" TEXT NOT NULL,"user_id" TEXT NOT NULL,"status" "KycStatus" NOT NULL DEFAULT 'not_started',"version" INTEGER NOT NULL DEFAULT 1,"legal_name" TEXT,"registration_number" TEXT,"tax_number" TEXT,"incorporation_country" TEXT,"incorporation_date" TIMESTAMP(3),"registered_address" TEXT,"website" TEXT,"business_activity" TEXT,"representative_name" TEXT,"representative_title" TEXT,"representative_email" TEXT,"representative_phone" TEXT,"representative_birth_date" TIMESTAMP(3),"beneficial_owners" JSONB,"terms_accepted" BOOLEAN NOT NULL DEFAULT false,"information_confirmed" BOOLEAN NOT NULL DEFAULT false,"submitted_at" TIMESTAMP(3),"reviewed_by_id" TEXT,"reviewed_at" TIMESTAMP(3),"decision_reason" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "corporate_kyc_applications_pkey" PRIMARY KEY ("id"));
CREATE TABLE "corporate_kyc_documents" ("id" TEXT NOT NULL,"application_id" TEXT NOT NULL,"type" TEXT NOT NULL,"storage_path" TEXT NOT NULL,"original_name" TEXT NOT NULL,"mime_type" TEXT NOT NULL,"size" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'uploaded',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "corporate_kyc_documents_pkey" PRIMARY KEY ("id"));
CREATE TABLE "corporate_kyc_audit_logs" ("id" TEXT NOT NULL,"application_id" TEXT NOT NULL,"actor_id" TEXT,"action" TEXT NOT NULL,"note" TEXT,"metadata" JSONB,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "corporate_kyc_audit_logs_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "corporate_kyc_applications_user_id_key" ON "corporate_kyc_applications"("user_id");
CREATE INDEX "corporate_kyc_applications_status_submitted_at_idx" ON "corporate_kyc_applications"("status","submitted_at");
CREATE INDEX "corporate_kyc_documents_application_id_type_idx" ON "corporate_kyc_documents"("application_id","type");
CREATE INDEX "corporate_kyc_audit_logs_application_id_created_at_idx" ON "corporate_kyc_audit_logs"("application_id","created_at");
ALTER TABLE "corporate_kyc_applications" ADD CONSTRAINT "corporate_kyc_applications_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "corporate_kyc_applications" ADD CONSTRAINT "corporate_kyc_applications_reviewed_by_id_fkey" FOREIGN KEY ("reviewed_by_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "corporate_kyc_documents" ADD CONSTRAINT "corporate_kyc_documents_application_id_fkey" FOREIGN KEY ("application_id") REFERENCES "corporate_kyc_applications"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "corporate_kyc_audit_logs" ADD CONSTRAINT "corporate_kyc_audit_logs_application_id_fkey" FOREIGN KEY ("application_id") REFERENCES "corporate_kyc_applications"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "corporate_kyc_audit_logs" ADD CONSTRAINT "corporate_kyc_audit_logs_actor_id_fkey" FOREIGN KEY ("actor_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
